#!/usr/bin/env bash
# Independent canned captures for the existing runner. They demonstrate grading
# mechanics, never observed model adherence/native selection or general savings.
write_s1_response() {
    local case_id="$1" response_path="$2"
    case "$case_id" in
        reduced-testing-carried-boundary)
            jq -n '
              def check($id;$action;$test;$claim;$reason): {
                check_id:$id,action:$action,claim_or_risk:$claim,method:"automated_test",test_scope:"unit",technique:"example",
                command:{argv:$test,cwd:"/workspace/filter"},
                check_ref_or_method:{reference_or_procedure:"Run the literal selected command and inspect its asserted boundary.",prerequisites:["Current filter and owning suite available."],exclusions:["No per-file or all-layer expansion."],expected_success:$claim,meaningful_failure:"The selected command observes a violation of its asserted boundary."},
                rationale:$reason,method_refs:["skills/assistant-verification/references/methods/unit.md"]};
              {scope:"Reuse existing coverage; add tests only for important uncovered behavior (user:reduced-tests). Preserve controlling CI and independently selected TDD.",
               policy_basis:{binding_constraints:[{kind:"required_check",value:"bash ci.sh",source_ref:"project:ci"}],preferences_applied:[],capability_limits:[]},
               test_change:"extend_existing",
               checks:[check("allow-owner";"reuse";["pytest","tests/test_owner.py::test_allow_owner"];"Accepted owner allowance remains protected.";"Current adequate coverage protects unchanged allowance."),
                       check("deny-nonowner";"extend";["pytest","tests/test_owner.py::test_deny_nonowner"];"Nonowners cannot read another owner data.";"Changed predicate has an important uncovered disclosure failure; allowance coverage does not assert denial."),
                       (check("required-ci";"run";["bash","ci.sh"];"Required CI suite passes.";"Controlling project suite needs execution, without new authoring.") | .method="static_validation" | .technique="schema_or_lint" | .method_refs=["skills/assistant-verification/references/methods/artifact-validation.md"] | del(.test_scope))],
               tdd_choice:{mode:true,applicable_check_ids:["deny-nonowner"],basis:"selected_technique",rationale:"Stable denial RED independently guides the important uncovered predicate."},
               omitted_checks_and_rationale:["Duplicate allowance assertions and speculative extra layers add no distinct important protection."],
               stop_rule:"Close selected important claims, controlling CI and meaningful TDD; expansion needs a named important gap, inadequate evidence and current selection/approval. Workers/review/resume retain user:reduced-tests."} as $decision |
              {verification_decision:$decision,evidence_assessment:{status:"planned",scope_and_evidence_refs:[],gaps_and_limitations:["Changed denial and required CI not executed."],next_action:"Carry source-bound constraints/decision to workers, review and resume; observe current denial RED before production."},
               current_task_packet:{packet_id:"filter-fix",name:"Complete owner filter",observable_increment:"Nonowners are denied",deliverable_type:"behavior",verification_decision:$decision,selected_check_ids:["allow-owner","deny-nonowner","required-ci"],binding_obligation_refs:$decision.policy_basis.binding_constraints,tdd_applies:true,acceptance_criteria:["Preserve allowance and deny cross-owner disclosure."],files_to_create:[],files_to_modify:["filter.py","tests/test_owner.py"],files_to_test:["tests/test_owner.py"],enabling_changes_included:[],depends_on:[],expected_success_signal:"Selected protection and required CI pass after meaningful RED",evidence_to_record:["Actual checks and source-bound scope"],deviation_rollback_rule:"Return material expansion to selection/approval.",red_check_id:"deny-nonowner",red_command:$decision.checks[1].command.argv,red_cwd:"/workspace/filter",expected_red_failure:$decision.checks[1].check_ref_or_method.meaningful_failure}}
            ' >"$response_path"
            ;;
        repair-expectations-switch-and-resume)
            jq -n '{build_repair_state:{attempt:3,max_attempts:3,no_progress_count:2,no_progress_limit:2,
              failure_signatures:["old-call-order:implementation-coupled/duplicate","deny-nonowner:product regression","dependency-load:baseline/environment","cache-race:unresolved"],
              progress_evidence:["Retained v1 attempts: initial plus two repairs; last two added no evidence. Switching checks, writer and session grants no allowance.","docs:permissions-v2 retires call ordering; never change production for it. Keep unique denial protection, baseline blocking relevance and unresolved cache cause."],
              plan_version:"v1",cumulative_attempt_count:3,status:"blocked",terminal_route:"debugging",evidence_ref:"capture:retained-v1"},changed_files:[]}' >"$response_path"
            ;;
        captured-defects-protection-and-cost)
            jq -n '
              def run($id;$argv;$exit;$child;$report): {id:$id,revision_ref:"fixture-a",argv:$argv,cwd:"/scratch/capture",host_toolchain:"synthetic local bash/python capture",exit_observation:$exit,child_observation:$child,report_observation:$report,evidence_refs:["capture:"+$id],limits:"Synthetic supplied fixture capture; no actual repository run."};
              def finding($id;$kind;$expected;$observed;$evidence;$recommendation): {id:$id,kind:$kind,scope_owner:"scoped test family / CI owner",expected_behavior:$expected,observed_behavior:$observed,evidence_refs:$evidence,consequence:"Protection or maintenance is bounded by the captured evidence.",competing_explanation:"None found within captured paths; other families excluded.",recommendation:$recommendation,limits:"No edit authority or native/general benefit evidence."};
              def maintenance($family;$claim;$defect;$remaining;$disposition;$rationale): {test_family:$family,important_claim:$claim,plausible_defect:$defect,remaining_unique_protection:$remaining,disposition:$disposition,retained_protection_or_obsolete_rationale:$rationale};
              def comparison($id;$status;$refs;$completed;$metrics;$conclusion): {id:$id,status:$status,baseline_run_refs:["capture:cost-control"],candidate_run_refs:$refs,completed_obligations_and_protection:$completed,changed_or_redundant_checks:"Duplicate preparation removed; distinct denial must remain.",conditions:"Same host/toolchain, cold cache; includes preparation/instrumentation.",measurements:$metrics,units_and_variability:"Elapsed ms; one sample each, variability unknown.",unmeasured_work:"Repair, review, API costs.",conclusion:$conclusion};
              {audit_summary:{status:"complete",answer:"Captured wrapper falsely passes child failure/missing report; stale fixture never reaches production. Retain denial; local paired time only.",baseline:"fixture-a; supplied synthetic local capture; clean original hashes",exclusions:["Other families, native activation, general savings."]},
               question_coverage:[{id:"protection",question:"Does the captured gate detect the faults?",status:"answered",evidence_refs:["capture:control","capture:fault","capture:early"]},{id:"cost",question:"Does completed protection have measured local cost?",status:"answered",evidence_refs:["capture:cost-control","capture:cost-candidate","capture:cost-failed"]}],
               audit_trace:[{path:"gate.sh -> dynamic check.py -> child -> report -> final exit",role_or_edge:"selector, fixture validation, child/report and final gate",observation:"observed",evidence_refs:["source:gate.sh","capture:fault","capture:early"],limits:"Only the named paths inspected; no omitted file found there."}],
               executed_checks:[run("control";["bash","gate.sh","valid"];"0";"0";"fresh accepted report"),run("fault";["bash","gate.sh","child-failure"];"0";"7";"missing"),run("early";["python3","check.py","stale.json"];"2";"production not reached";"schema rejected"),run("cost-control";["bash","suite.sh","full"];"0";"accepted allowance and denial completed";"fresh protection report"),run("cost-candidate";["bash","suite.sh","dedup"];"0";"accepted allowance and denial completed";"fresh protection report"),run("cost-failed";["bash","suite.sh","broken"];"2";"setup failed";"no protection report")],
               findings:[finding("swallowed-child";"reproduced_defect";"Child failure and missing report reject final gate.";"child 7; wrapper 0; missing report";["capture:fault","source:gate.sh"];"Propagate child status and require a fresh report in a separately authorized repair."),
                 finding("early-fixture";"reproduced_defect";"Fixture exercises production rejection branch.";"schema rejected fixture before production branch";["capture:early"];"Refresh fixture fidelity before claiming production rejection coverage."),
                 (finding("duplicate-allow";"hypothesis";"Retain adequate allowance protection.";"Two assertions protect the same allowance claim.";["source:accepted-auth"];"Consolidate only with retained allowance protection.") + {maintenance:maintenance("same-owner-twice";"owner allowance";"owner wrongly denied";"allow-owner";"consolidate";"allow-owner retains accepted allowance protection")}),
                 (finding("distinct-denial";"hypothesis";"Deny cross-owner disclosure.";"Similar test protects a distinct fault.";["source:accepted-auth"];"Keep distinct denial protection.") + {maintenance:maintenance("deny-other-owner";"cross-owner denial";"nonowner reads data";"unique denial assertion";"keep";"No other retained assertion detects cross-owner disclosure.")}),
                 (finding("obsolete-order";"hypothesis";"Any equivalent permission helper is accepted.";"Internal call ordering is obsolete.";["source:accepted-auth"];"Recommend removing obsolete assertion only; no action authority.") + {maintenance:maintenance("old-call-order";"accepted permission semantics";"permission decision wrong";"allowance and denial retained; ordering not accepted behavior";"remove";"source:accepted-auth retires internal call ordering")}),
                 finding("local-cost";"supported_cost";"Equivalent completed allowance and denial protection.";"40 ms versus 30 ms in completed pair; failed pair incomparable.";["capture:cost-control","capture:cost-candidate","capture:cost-failed"];"Only a local elapsed-time observation; general savings unknown.")],
               probe_results:[{id:"p1",authority_ref:"capture:p1",isolated_input:"/scratch/copy disposable",baseline_control:"capture:control accepted valid input",expected_detection:"Final gate rejects injected child failure/missing report.",observed_detection:"capture:fault final 0 child 7 report missing",run_refs:["control","fault"],cleanup:"capture:p1 disposable copy removed",original_hash_evidence:"capture:p1 pre=aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa post=aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa unchanged",limits:"Synthetic supplied fixture probe; no actual mutation."}],
               performance_comparisons:[comparison("completed-pair";"comparable";["capture:cost-candidate"];"Both completed accepted allowance and denial protection.";"control 40 ms; candidate 30 ms";"Captured local elapsed time lower by 10 ms; no general savings claim."),comparison("failed-pair";"incomparable";["capture:cost-failed"];"Candidate failed setup and never exercised denial.";"control 40 ms; failed candidate 5 ms";"No savings: setup failed before denial protection completed.")],
               evidence_gaps:[],next_action:"Return recommendations to workflow for separately authorized repair; no edits or dispatch."}
            ' >"$response_path"
            ;;
        inspect-only-missing-evidence)
            jq -n '{audit_summary:{status:"partial",answer:"Inspected wrapper propagates status, but discovery/fixtures and cost are unobserved.",baseline:"local source inspection only; revision identity unavailable",exclusions:["No authorized diagnostics, native activation or company-PC evidence."]},
              question_coverage:[{id:"protection",question:"Does discovery/fixture protection hold?",status:"unresolved",evidence_refs:["source:wrapper"],missing_observation:"Discovery and fixture branch observations unavailable.",next_step:"Obtain bounded local diagnostic authority and observations."}],
              audit_trace:[{path:"wrapper -> exit",role_or_edge:"status forwarding",observation:"observed",evidence_refs:["source:wrapper"],limits:"Source only; dynamic discovery/fixtures unavailable."}],executed_checks:[],findings:[],
              performance_comparisons:[{id:"missing-pair",status:"incomparable",baseline_run_refs:[],candidate_run_refs:[],completed_obligations_and_protection:"Unknown; no completed paired work.",changed_or_redundant_checks:"None observed.",conditions:"No comparable capture.",measurements:"Unavailable.",units_and_variability:"Unavailable.",unmeasured_work:"All execution, maintenance and cost.",conclusion:"No savings: no actual paired completed-work evidence."}],
              evidence_gaps:["No diagnostic authority/finite allowance, discovery/fixture evidence or metrics. Planned probes are unexecuted; working-input injection and count-based deletion rejected."],next_action:"Request bounded local diagnostic authority and missing observations; do not inject, delete or dispatch."}' >"$response_path"
            ;;
        *) return 1 ;;
    esac
}
